constraint.cypher:
MATCH (t:Type {name: 'TokenAuthFilter'})-[:DECLARES]->(m:Method)-[:INVOKES]->(q:Method)
    WHERE NOT t:Test AND coalesce(q.name, last(split(split(q.signature, '(')[0], ' '))) = 'getQueryString' AND EXISTS { MATCH (m)-[:INVOKES]->(:Method:LogCall) }
    RETURN DISTINCT m AS Element, t.fqn AS Fqn, 'query string logged' AS Detail

MATCH (t:Type {name: 'GexListener'})-[:DECLARES]->(m:Method:MessageConsumer)
    WHERE NOT t:Test AND NOT EXISTS { MATCH (m)-[:INVOKES*1..3]->(:Method)<-[:DECLARES]-(:Type:IdempotencyStore) }
    RETURN DISTINCT m AS Element, t.fqn AS Fqn, m.signature AS Detail
